import React from 'react'
import { render, screen } from '@testing-library/react'
import { describe, it, expect, vi } from 'vitest'
import App from './App'

// Mock fetch
global.fetch = vi.fn()

function createFetchResponse(data) {
  return { json: () => new Promise((resolve) => resolve(data)), ok: true }
}

describe('App', () => {
  beforeEach(() => {
    fetch.mockReset()
  })

  it('renders the PR Viewer title', async () => {
    fetch.mockResolvedValueOnce(createFetchResponse([]))
    render(<App />)
    expect(screen.getByText('PR Viewer')).toBeInTheDocument()
