// Mock fetch globally
vi.stubGlobal('fetch', vi.fn())

function createFetchResponse(data: any) {
  return { json: () => new Promise((resolve) => resolve(data)), ok: true }
}

describe('App', () => {
  beforeEach(() => {
    (fetch as any).mockReset()
    process.env.GITHUB_TOKEN = 'mock-token'
  })

  it('renders the PR Viewer title and repository dropdown', async () => {
    (fetch as any).mockResolvedValueOnce(createFetchResponse([{ name: 'repo1' }, { name: 'repo2' }]))
    await act(async () => {
      render(<App />)
    })

    expect(screen.getByText('PR Viewer')).toBeInTheDocument()
    expect(screen.getByText('Select a repository')).toBeInTheDocument()

    await waitFor(() => {
      expect(screen.getByText('repo1')).toBeInTheDocument()
      expect(screen.getByText('repo2')).toBeInTheDocument()
    })
  })

  it('displays an error message when fetching repos fails', async () => {
    (fetch as any).mockRejectedValueOnce(new Error('API Error'))
    await act(async () => {
      render(<App />)
    })

    await waitFor(() => {
      expect(screen.getByText('Failed to fetch repositories. Please try again later.')).toBeInTheDocument()
    })
  })

  it('fetches and displays pull requests when a repo is selected', async () => {
    (fetch as any).mockResolvedValueOnce(createFetchResponse([{ name: 'repo1' }]))
    (fetch as any).mockResolvedValueOnce(createFetchResponse([
      { id: 1, title: 'PR 1', html_url: 'https://github.com/OpenDevin/repo1/pull/1' },
      { id: 2, title: 'PR 2', html_url: 'https://github.com/OpenDevin/repo1/pull/2' }
    ]))

    await act(async () => {
      render(<App />)
    })

    await waitFor(() => {
      expect(screen.getByText('repo1')).toBeInTheDocument()
    })

    await act(async () => {
      const select = screen.getByRole('combobox') as HTMLSelectElement
      select.value = 'repo1'
      select.dispatchEvent(new Event('change', { bubbles: true }))
    })

    await waitFor(() => {
      expect(screen.getByText('PR 1')).toBeInTheDocument()
      expect(screen.getByText('PR 2')).toBeInTheDocument()
    })
  })
})
"""

